//! Zero-allocation, no_std command parser shared with other Xila executables.
//! Errors and help text are generated by getargs-derive at compile time.

use alloc::string::String;
use getargs_derive::{GetArgs, Subcommand};

/// Install or upgrade a package: a .xpk path, or a package name from the
/// configured repositories (`name` or `name@version`).
#[derive(Debug, Clone, PartialEq, Eq, GetArgs)]
pub struct Install<'a> {
    /// A .xpk path in the Xila virtual filesystem, or a package name.
    pub package: &'a str,
    /// Local archive only: verify with this raw Ed25519 developer key file
    /// instead of the repositories.
    #[arg(long = "public-key", conflicts_with = "allow_untrusted")]
    pub public_key: Option<&'a str>,
    /// Local archive only: accept an unknown publisher, still checking hashes.
    #[arg(long = "allow-untrusted", conflicts_with = "public_key")]
    pub allow_untrusted: bool,
    /// Use this repository when several provide the package.
    #[arg(long)]
    pub repository: Option<&'a str>,
}

/// What `Install::package` designates.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Target<'a> {
    Archive(&'a str),
    Package {
        name: &'a str,
        version: Option<&'a str>,
    },
}

impl<'a> Install<'a> {
    /// Package names never contain `/`; VFS archive paths always do.
    pub fn target(&self) -> Target<'a> {
        if self.package.contains('/') {
            Target::Archive(self.package)
        } else {
            match self.package.split_once('@') {
                Some((name, version)) => Target::Package {
                    name,
                    version: Some(version),
                },
                None => Target::Package {
                    name: self.package,
                    version: None,
                },
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, GetArgs)]
pub struct RepositoryCommand<'a> {
    #[command(subcommand)]
    pub command: RepositoryOperation<'a>,
}

#[derive(Debug, Clone, PartialEq, Eq, Subcommand)]
pub enum RepositoryOperation<'a> {
    /// Add a repository; asks to confirm its root key fingerprint unless
    /// --root-key gives the key.
    Add {
        /// Local name, e.g. community.
        name: &'a str,
        /// HTTPS base URL, e.g. https://registry.example.org.
        url: &'a str,
        /// Root key obtained out of band (canonical base64); skips the prompt.
        #[arg(long = "root-key")]
        root_key: Option<&'a str>,
        /// Accept the fetched root key without asking (scripts only).
        #[arg(long)]
        yes: bool,
    },
    /// List configured repositories with their root key fingerprints.
    List,
    /// Remove a repository; installed packages are kept.
    Remove {
        /// Local name of the repository.
        name: &'a str,
    },
}

/// Show one package: the installed copy, or what the repositories offer.
#[derive(Debug, Clone, PartialEq, Eq, GetArgs)]
pub struct Information<'a> {
    /// Package name, e.g. xila.clock, or name@version.
    pub package: &'a str,
    /// Look only in this repository (implies a repository lookup).
    #[arg(long)]
    pub repository: Option<&'a str>,
}

impl<'a> Information<'a> {
    /// The package name and the requested version, if any.
    pub fn name_and_version(&self) -> (&'a str, Option<&'a str>) {
        match self.package.split_once('@') {
            Some((name, version)) => (name, Some(version)),
            None => (self.package, None),
        }
    }

    /// Whether to describe the repositories' version instead of the
    /// installed one: a version or a repository was given.
    pub fn queries_repositories(&self) -> bool {
        self.repository.is_some() || self.package.contains('@')
    }
}

/// Search the configured repositories' signed indexes.
#[derive(Debug, Clone, PartialEq, Eq, GetArgs)]
pub struct Search<'a> {
    /// Part of a package name (case-insensitive); every package when omitted.
    pub query: Option<&'a str>,
    /// Search only this repository.
    #[arg(long)]
    pub repository: Option<&'a str>,
}

#[derive(Debug, Clone, PartialEq, Eq, Subcommand)]
pub enum Command<'a> {
    /// Verify and install a package.
    Install(Install<'a>),
    /// Verify and install a newer version of an installed package, keeping its data.
    Upgrade(Install<'a>),
    /// Remove an installed package; its user data is kept.
    Remove {
        /// Package name, e.g. xila.clock.
        name: &'a str,
    },
    /// Finish or undo an interrupted package operation.
    Recover,
    /// List installed application bundles.
    List,
    /// Show an installed package offline, or, when it is not installed or a
    /// version or --repository is given, the newest compatible version in the
    /// configured repositories.
    Info(Information<'a>),
    /// Find packages in the configured repositories by name.
    Search(Search<'a>),
    /// Manage package repositories.
    Repository(RepositoryCommand<'a>),
}

/// Native CLI for installing signed Xila application packages.
#[derive(Debug, Clone, PartialEq, Eq, GetArgs)]
#[command(name = "package", version)]
struct Cli<'a> {
    #[command(subcommand)]
    command: Command<'a>,
}

pub fn parse<'a>(args: &'a [String]) -> Result<Command<'a>, getargs_derive::Error<'a>> {
    Cli::from_args(args.iter().map(String::as_str)).map(|cli| cli.command)
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloc::{string::ToString, vec, vec::Vec};

    fn args(parts: &[&str]) -> Vec<String> {
        parts.iter().map(|part| (*part).to_string()).collect()
    }

    fn install(parts: &[&str]) -> Install<'static> {
        let input: &'static [String] = args(parts).leak();
        match parse(input).unwrap() {
            Command::Install(install) => install,
            other => panic!("unexpected {other:?}"),
        }
    }

    #[test]
    fn default_install_requires_a_trusted_signer() {
        let install = install(&["install", "/temporary/example.xpk"]);
        assert_eq!(install.target(), Target::Archive("/temporary/example.xpk"));
        assert_eq!(install.public_key, None);
        assert!(!install.allow_untrusted);
    }

    #[test]
    fn unfamiliar_publisher_requires_an_explicit_override_or_key() {
        assert!(
            install(&["install", "/temporary/example.xpk", "--allow-untrusted"]).allow_untrusted
        );
        assert_eq!(
            install(&["install", "./x.xpk", "--public-key", "/keys/user.pub"]).public_key,
            Some("/keys/user.pub")
        );
        let input = args(&[
            "install",
            "/x.xpk",
            "--allow-untrusted",
            "--public-key",
            "/k.pub",
        ]);
        assert!(parse(&input).is_err());
    }

    #[test]
    fn package_names_select_repositories() {
        assert_eq!(
            install(&["install", "xila.clock"]).target(),
            Target::Package {
                name: "xila.clock",
                version: None
            }
        );
        let pinned = install(&["install", "xila.clock@0.1.0", "--repository", "xila"]);
        assert_eq!(
            pinned.target(),
            Target::Package {
                name: "xila.clock",
                version: Some("0.1.0")
            }
        );
        assert_eq!(pinned.repository, Some("xila"));
    }

    #[test]
    fn repository_commands() {
        let input = args(&[
            "repository",
            "add",
            "community",
            "https://registry.example.org",
            "--root-key",
            "AJEDFQ2MPtUO0vu/BnC7xX5Ag8sBuq6DF5+ShKfCQgU=",
        ]);
        assert_eq!(
            parse(&input),
            Ok(Command::Repository(RepositoryCommand {
                command: RepositoryOperation::Add {
                    name: "community",
                    url: "https://registry.example.org",
                    root_key: Some("AJEDFQ2MPtUO0vu/BnC7xX5Ag8sBuq6DF5+ShKfCQgU="),
                    yes: false,
                }
            }))
        );
        let input = args(&["repository", "remove", "community"]);
        assert_eq!(
            parse(&input),
            Ok(Command::Repository(RepositoryCommand {
                command: RepositoryOperation::Remove { name: "community" }
            }))
        );
        let input = args(&["repository", "list"]);
        assert!(parse(&input).is_ok());
        assert!(parse(&args(&["repository", "add", "only-name"])).is_err());
    }

    #[test]
    fn lifecycle_commands() {
        let input = args(&["upgrade", "xila.clock"]);
        match parse(&input).unwrap() {
            Command::Upgrade(upgrade) => assert_eq!(
                upgrade.target(),
                Target::Package {
                    name: "xila.clock",
                    version: None
                }
            ),
            other => panic!("unexpected {other:?}"),
        }
        let input = args(&["upgrade", "/temporary/clock.xpk", "--allow-untrusted"]);
        assert!(matches!(
            parse(&input),
            Ok(Command::Upgrade(Install {
                allow_untrusted: true,
                ..
            }))
        ));
        let input = args(&["remove", "xila.clock"]);
        assert_eq!(parse(&input), Ok(Command::Remove { name: "xila.clock" }));
        assert!(parse(&args(&["remove"])).is_err());
        assert_eq!(parse(&args(&["recover"])), Ok(Command::Recover));
    }

    #[test]
    fn information_and_search() {
        let input = args(&["info", "xila.clock"]);
        let Ok(Command::Info(information)) = parse(&input) else {
            panic!("info not parsed");
        };
        assert_eq!(information.name_and_version(), ("xila.clock", None));
        assert!(!information.queries_repositories());

        let input = args(&["info", "xila.clock@0.2.0"]);
        let Ok(Command::Info(information)) = parse(&input) else {
            panic!("info not parsed");
        };
        assert_eq!(
            information.name_and_version(),
            ("xila.clock", Some("0.2.0"))
        );
        assert!(information.queries_repositories());

        let input = args(&["info", "xila.clock", "--repository", "xila"]);
        let Ok(Command::Info(information)) = parse(&input) else {
            panic!("info not parsed");
        };
        assert_eq!(information.repository, Some("xila"));
        assert!(information.queries_repositories());
        assert!(parse(&args(&["info"])).is_err());

        assert_eq!(
            parse(&args(&["search"])),
            Ok(Command::Search(Search {
                query: None,
                repository: None
            }))
        );
        let input = args(&["search", "clock", "--repository", "community"]);
        assert_eq!(
            parse(&input),
            Ok(Command::Search(Search {
                query: Some("clock"),
                repository: Some("community")
            }))
        );
    }

    #[test]
    fn help_and_listing() {
        assert_eq!(parse(&args(&["list"])), Ok(Command::List));
        for parts in [vec!["--help"], vec!["install", "--help"], vec!["--version"]] {
            let input = args(&parts);
            let error = parse(&input).unwrap_err();
            assert!(error.is_help() || error.is_version());
        }
        assert!(Cli::HELP.contains("Usage: package"));
        assert!(Cli::HELP.contains("repository"));
        assert!(Cli::HELP.contains("upgrade"));
        assert!(Cli::HELP.contains("recover"));
        assert!(Cli::HELP.contains("info"));
        assert!(Cli::HELP.contains("search"));
    }
}
